import sys
import time
import psutil
import logging
from functools import wraps
from easyprocess import EasyProcess
from selenium.common.exceptions import ElementClickInterceptedException
from taf.selenium.sbts_fsm3.common.common import LocalBasicPage
from taf.selenium.sbts_fsm3.common.utils import check_if_selenium_required_process_exist


class Debug(LocalBasicPage):
    def __init__(self, webdriver, screenshot_dir):
        super(Debug, self).__init__(webdriver, screenshot_dir=screenshot_dir)


def catch_interface_exception(func):
    """
    Method to catch exception and save screen shot if function raises an error
    """

    @wraps(func)
    def interface_func(*args, **kwargs):
        try:
            outcome = func(*args, **kwargs)
        except Exception:
            driver = args[0]._sbts_fsm3__driver
            screenshot_dir = args[0]._screenshot_dir
            Debug(driver, screenshot_dir).save_screenshot('{}'.format(func.__name__))
            logging.info("Current used Firefox version is: %s", EasyProcess(["firefox", "--version"]).call().stdout)
            logging.info("Current used python version is: %s", sys.version.split(' ')[0])
            logging.info('cpu use {} percent, memory use {} percent'.format(psutil.cpu_percent(),
                                                                            psutil.virtual_memory().percent))
            check_if_selenium_required_process_exist()
            raise
        return outcome

    return interface_func


def catch_intercepted_click_exception(func):
    """
    Catches ElementClickInterceptedException when button or place we want to click
    is covered by pop-up (e.g. "Nemuadmin logged in"). After 5 retries (total 15 seconds of retrying)
    method raises original exception..
    """

    @wraps(func)
    def interface_func(*args, **kwargs):
        retry = kwargs.pop('retry', None) or 5
        for retries in range(retry):
            try:
                outcome = func(*args, **kwargs)
                if func.__name__ == 'logout':
                    args[0].close_browser(sbts=kwargs.get('sbts', None))
                return outcome
            except ElementClickInterceptedException:
                time.sleep(3)
                continue
        else:
            raise ElementClickInterceptedException("Could not click button after {} retries "
                                                   "as it is covered by other element.".format(retry))

    return interface_func
